import {isFloor} from './cave-layout.js';
import {campaignBossHome} from './boss-arena-space.js';
import {bossDamage} from './bosses.js';
export const MYSTIC_RULES=Object.freeze({version:2,dance:6,reveal:2,response:8,recovery:4,transform:3,warning:2,shots:4,exhaust:6,fireLife:5,fireDamage:6,beamDamage:14,fireCap:128,weaknessMinimum:12});
const d=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y),point=n=>({x:n.x,y:n.y}),inside=(room,p)=>p&&Number.isInteger(p.x)&&Number.isInteger(p.y)&&isFloor(room,p.x,p.y);
export const mysticActive=b=>b?.boss===true&&b.bossIndex===3&&b.mirage?.version===2;
export const mysticBoss=room=>room.enemies.find(b=>mysticActive(b)&&b.hp>0);
export const mysticCopy=n=>n?.type==='mysticCopy';
export const mysticTargets=room=>room.enemies.filter(b=>mysticActive(b)&&b.hp>0&&b.mirage.phase===1).flatMap(b=>b.mirage.copies.filter(c=>c.hp>0));
export const mysticBodies=room=>[...room.enemies.filter(b=>mysticActive(b)&&b.hp>0&&b.mirage.phase===1),...mysticTargets(room)];
export const mysticBodyCells=room=>mysticBodies(room).flatMap(b=>[-1,0,1].flatMap(y=>[-1,0,1].map(x=>({x:b.x+x,y:b.y+y}))));
export const mysticBodyBlocks=(room,x,y)=>mysticBodies(room).some(b=>Math.abs(x-b.x)<=1&&Math.abs(y-b.y)<=1);
export function mysticApproach(b,p,room,walkable,pathTo){if(d(b,p)<=2&&walkable(room,p.x,p.y))return point(p);return [[0,2],[2,0],[0,-2],[-2,0]].map(([x,y])=>({x:b.x+x,y:b.y+y})).filter(q=>walkable(room,q.x,q.y)).map(q=>({q,path:pathTo(room,p,q)})).filter(a=>a.path.length||d(a.q,p)===0).sort((a,z)=>a.path.length-z.path.length)[0]?.q||point(p);}
export function mysticEscape(room,p,walkable){if(!mysticBodyBlocks(room,p.x,p.y))return null;const candidates=[];for(let y=1;y<room.rows-1;y++)for(let x=1;x<room.cols-1;x++)if(walkable(room,x,y))candidates.push({x,y});return candidates.sort((a,b)=>d(a,p)-d(b,p)||a.y-b.y||a.x-b.x)[0]||null;}
export const mysticSites=room=>{const x=Math.floor(room.cols/2),y=Math.floor(room.rows/2);return [[0,-4],[4,-2],[4,2],[0,4],[-4,2],[-4,-2]].map(([a,b])=>({x:x+a,y:y+b}));};
export function rasterLine(a,b){const out=[],dx=b.x-a.x,dy=b.y-a.y,n=Math.max(Math.abs(dx),Math.abs(dy));for(let i=0;i<=n;i++){const q={x:Math.round(a.x+dx*i/(n||1)),y:Math.round(a.y+dy*i/(n||1))};if(!out.some(p=>d(p,q)===0))out.push(q);}return out;}
export const mysticReserved=(room,p)=>room.enemies.some(mysticActive)&&(d(p,{x:Math.floor(room.cols/2),y:Math.floor(room.rows/2)})<=3||mysticSites(room).some((q,i,a)=>rasterLine(q,a[(i+1)%6]).some(t=>Math.abs(t.x-p.x)<=1&&Math.abs(t.y-p.y)<=1)));
export function enableMystic(b,room){if(!b?.boss||b.bossIndex!==3)throw Error('Boss Místico only');Object.assign(b,center(room));b.windup=null;b.phase=1;b.exposedUntil=-1;b.recoverUntil=3;b.mirage={version:2,state:'rest',phase:1,cycle:0,lastBegin:-1,lastResolved:-1,nextCycle:4,serial:0,copies:[],slots:[],moves:[],ringOffset:0,moveCount:0,danceStart:-1,danceEnd:-1,revealAt:-1,huntAt:-1,deadline:-1,openAt:-1,openUntil:-1,hitAt:-1,shatterAt:-1,shatterFrom:null,chaseStart:-1,nextAim:-1,shot:null,lastShot:null,shots:0,lastPlayer:null,fire:[],fireHitBeat:-1};
 for(const node of room.nodes)if(mysticReserved(room,node)){const options=[];for(let y=2;y<room.rows-2;y++)for(let x=2;x<room.cols-2;x++){const q={x,y};if(isFloor(room,x,y)&&!mysticReserved(room,q)&&d(q,room.exit)>2&&!room.nodes.some(n=>n!==node&&n.hp>0&&d(n,q)<2))options.push(q);}const q=options.sort((a,z)=>d(a,node)-d(z,node)||a.y-z.y||a.x-z.x)[0];if(!q)throw Error('No safe vein relocation');Object.assign(node,q);}return b;}
function emit(s,b,type,beat,data={}){s.run.events.push({type,id:`mystic2:${s.run.room.seed}:${b.id}:${++b.mirage.serial}:${type}:${beat}`,bossIndex:3,sourceId:b.id,beat,x:b.x,y:b.y,...data});}
const center=campaignBossHome;
function addFire(b,room,tiles,beat,source){const m=b.mirage;for(const p of tiles){if(!inside(room,p))continue;let f=m.fire.find(q=>d(q,p)===0);if(f){f.until=Math.max(f.until,beat+5);continue;}if(m.fire.length>=128)m.fire.shift();m.fire.push({...p,born:beat,activeAt:beat+1,until:beat+5,source});}}
export const activeMysticFire=(b,beat)=>b.mirage.fire.filter(f=>beat>=f.activeAt&&beat<f.until);
export const mysticFireAt=(b,p,beat)=>activeMysticFire(b,beat).some(f=>d(f,p)===0);
function cycle(s,b,beat){const m=b.mirage,a=mysticSites(s.run.room),parity=(s.run.room.seed+m.cycle)%2;let offset=parity;const clear=n=>[0,2,4].every(i=>{const p=a[(i+n)%6];return Math.abs(p.x-s.run.player.x)>1||Math.abs(p.y-s.run.player.y)>1;});if(!clear(offset))offset=1-offset;if(!clear(offset))throw Error('No safe starting orbit');m.cycle++;m.ringOffset=offset;m.moveCount=0;const positions=[0,2,4].map(i=>a[(i+offset)%6]);Object.assign(b,positions[0]);m.copies=positions.slice(1).map((p,i)=>({id:-(900000+b.id*10+i),type:'mysticCopy',owner:b.id,slot:i,...p,hp:1,maxHp:1,goneAt:-1}));m.slots=positions;m.moves=[];m.danceStart=beat;m.danceEnd=beat+6;m.revealAt=m.danceEnd;m.huntAt=m.revealAt+2;m.deadline=m.huntAt+8;m.openAt=m.openUntil=-1;m.shot=null;m.state='dance';emit(s,b,'mysticAppear',beat);}
function dance(s,b,beat){const m=b.mirage;if(beat<=m.danceStart||(beat-m.danceStart)%2!==0)return;const a=mysticSites(s.run.room),step=m.moveCount+1,actors=[b,...m.copies],dest=actors.map((n,i)=>a[(i*2+m.ringOffset+step)%6]);
 // Do not land a moving 3x3 body on the miner. A blocked arc waits this pulse.
 if(dest.some(p=>Math.abs(p.x-s.run.player.x)<=1&&Math.abs(p.y-s.run.player.y)<=1))return;
 m.moves=actors.map((n,i)=>({id:n.id,from:point(n),to:point(dest[i]),started:beat,due:beat+1}));for(const [i,n]of actors.entries()){addFire(b,s.run.room,rasterLine(n,dest[i]),beat,i?'copy':'boss');Object.assign(n,dest[i]);}m.moveCount=step;m.slots=dest;emit(s,b,'mysticTrail',beat);}
function shatter(s,b,beat){const m=b.mirage;m.phase=b.phase=2;m.state='shatter';m.shatterAt=beat;m.shatterFrom=point(b);m.shot=null;m.moves=[];for(const c of m.copies){c.hp=0;c.goneAt=beat;}Object.assign(b,center(s.run.room));m.slots=[];b.exposedUntil=-1;emit(s,b,'mysticShatter',beat);}
export function mysticShotTiles(room,from,target){let dx=target.x-from.x,dy=target.y-from.y;if(!dx&&!dy)dy=1;const length=Math.hypot(dx,dy);dx/=length;dy/=length;const out=[],seen=new Set();for(let t=0;t<Math.hypot(room.cols,room.rows);t+=.15){const x=Math.round(from.x+dx*t),y=Math.round(from.y+dy*t);if(!isFloor(room,x,y))break;const key=x+','+y;if(!seen.has(key)){out.push({x,y});seen.add(key);}}return out;}
function predict(s,b){const m=b.mirage,p=s.run.player,prior=m.lastPlayer||p,dx=p.x-prior.x,dy=p.y-prior.y,len=Math.hypot(dx,dy)||1,index=m.shots,lead=index%2?3:0;let q={x:Math.round(p.x+dx/len*lead),y:Math.round(p.y+dy/len*lead)};if(index===2)q={x:p.x+(s.run.room.seed%2?2:-2),y:p.y};q.x=Math.max(1,Math.min(s.run.room.cols-2,q.x));q.y=Math.max(1,Math.min(s.run.room.rows-2,q.y));if(!inside(s.run.room,q))q=point(p);return q;}
function aim(s,b,beat){const m=b.mirage,target=predict(s,b);m.lastPlayer=point(s.run.player);m.shots++;m.shot={from:point(b),target,tiles:mysticShotTiles(s.run.room,b,target),started:beat,due:beat+2,index:m.shots};m.nextAim=beat+2;emit(s,b,'mysticAim',beat,{target,due:beat+2});}
function chase(s,b,beat){const m=b.mirage;m.state='chase';m.chaseStart=beat;m.shots=0;m.lastPlayer=null;m.shot=null;b.exposedUntil=-1;aim(s,b,beat);}
function begin(s,b,beat){const m=b.mirage;if(beat<=m.lastBegin)return;m.lastBegin=beat;m.fire=m.fire.filter(f=>beat<f.until);if(beat<4)return;if(m.phase===1&&b.hp<=b.maxHp/2){shatter(s,b,beat);return;}
 if(m.phase===1){if(m.state==='rest'&&beat>=m.nextCycle)cycle(s,b,beat);if(m.state==='dance'){dance(s,b,beat);if(beat>=m.danceEnd)m.state='reveal';}if(m.state==='reveal'&&beat>=m.huntAt)m.state='hunt';if(m.state==='hunt'&&beat>=m.deadline){m.state='rest';m.nextCycle=beat+1;}if(m.state==='open'&&beat>=m.openUntil){m.state='rest';m.nextCycle=beat+1;}if(['reveal','hunt'].includes(m.state))emit(s,b,'mysticClue',beat);return;}
 if(m.state==='shatter'&&beat>=m.shatterAt+3)chase(s,b,beat);else if(m.state==='exhausted'&&beat>=m.openUntil)chase(s,b,beat);
}
function resolve(s,b,beat,cb){const m=b.mirage;if(beat<=m.lastResolved)return;m.lastResolved=beat;let damage=0,reason='fire';const w=m.shot;
 if(w&&beat>=w.due){m.lastShot={...w,impact:beat};m.shot=null;addFire(b,s.run.room,w.tiles,beat,'beam');emit(s,b,'mysticShot',beat,{from:w.from,target:w.target,tiles:w.tiles});if(w.tiles.some(p=>d(p,s.run.player)===0)){damage=14;reason='beam';}if(m.shots<4)aim(s,b,beat);else{m.state='exhausted';m.openAt=beat+1;m.openUntil=beat+7;b.exposedUntil=m.openUntil-1;m.fire=m.fire.filter(f=>d(f,b)>2);emit(s,b,'mysticExhausted',beat);}}
 if(mysticFireAt(b,s.run.player,beat))damage=Math.max(damage,6);if(damage&&m.fireHitBeat!==beat&&!cb.airborne?.(beat)){m.fireHitBeat=beat;emit(s,b,'mysticContact',beat,{damage,reason});cb.contact(b,damage,beat);}}
const stopped=s=>!s.run||s.run.room.cleared||s.run.recovery?.active||s.run.rest?.active||s.run.abyss?.cardChoice;
export function mysticAdvance(s,beat,cb){if(stopped(s))return;const b=mysticBoss(s.run.room);if(!b)return;for(let at=b.mirage.lastResolved+1;at<beat;at++){begin(s,b,at);resolve(s,b,at,cb);if(stopped(s))return;}begin(s,b,beat);}
export function mysticResolve(s,beat,cb){if(stopped(s))return;const b=mysticBoss(s.run.room);if(b)resolve(s,b,beat,cb);}
export const mysticOpen=(b,beat)=>mysticActive(b)&&['open','exhausted'].includes(b.mirage.state)&&beat>=b.mirage.openAt&&beat<b.mirage.openUntil;
export function mysticCopyHit(s,c,beat,visual){const b=mysticBoss(s.run.room);if(!b||!mysticCopy(c)||c.hp<=0||!b.mirage.copies.includes(c))return false;if(b.mirage.state!=='hunt'){if(visual){visual.outcome='blocked';visual.damage=0;}return false;}c.hp=0;c.goneAt=beat;if(visual){visual.outcome='stun';visual.damage=0;}emit(s,b,'mysticFalse',beat,{x:c.x,y:c.y});return true;}
export function mysticDamage(s,b,amount,beat,direct){const m=b.mirage;if(m.phase===2&&!mysticOpen(b,beat))return 0;if(m.phase===1&&!mysticOpen(b,beat)){if(!direct||m.state!=='hunt'||beat>=m.deadline)return 0;m.openAt=beat;m.openUntil=beat+5;m.state='open';for(const c of m.copies){c.hp=0;c.goneAt=beat;}b.exposedUntil=m.openUntil-1;emit(s,b,'mysticInterrupt',beat);}const value=bossDamage(b,Math.max(12,amount*4),beat),actual=m.phase===1?Math.min(value,Math.max(0,b.hp-b.maxHp/2)):value;if(actual>0)m.hitAt=beat;return actual;}
export function mysticCleanup(b){if(!mysticActive(b))return;const m=b.mirage;m.state='dead';m.shot=null;m.moves=[];m.fire=[];for(const c of m.copies)c.hp=0;b.windup=null;}
export function mysticCaption(b,beat){const m=b.mirage;return m.state==='dance'?'SALTE SOBRE O RASTRO DE FOGO':m.state==='reveal'?'OBSERVE O FECHO QUE SE ABRE':m.state==='hunt'?'ACERTE O VERDADEIRO · '+Math.max(0,m.deadline-Math.floor(beat)):m.state==='open'?'FECHO ABERTO · ATAQUE!':m.state==='shatter'?'O CORPO SE ROMPEU':m.state==='chase'?'CABEÇA INTANGÍVEL · DESVIE DA MIRA':m.state==='exhausted'?'EXAUSTO · ATAQUE! · '+Math.max(0,m.openUntil-Math.floor(beat)):'AS MIRAGENS VÃO VOLTAR';}
export function validMystic(b,room){if(b.mirage===undefined)return true;if(!mysticActive(b))return false;const m=b.mirage,int=Number.isSafeInteger,p=q=>inside(room,q);if(!['rest','dance','reveal','hunt','open','shatter','chase','exhausted','dead'].includes(m.state)||![1,2].includes(m.phase)||b.phase!==m.phase||b.windup!==null||!['cycle','lastBegin','lastResolved','nextCycle','serial','ringOffset','moveCount','danceStart','danceEnd','revealAt','huntAt','deadline','openAt','openUntil','hitAt','shatterAt','chaseStart','nextAim','shots','fireHitBeat'].every(k=>int(m[k]))||m.lastResolved>m.lastBegin||m.serial<0||m.serial>1e7||m.cycle<0||m.shots<0||m.shots>4||!Array.isArray(m.copies)||![0,2].includes(m.copies.length)||!Array.isArray(m.moves)||m.moves.length>3||!Array.isArray(m.slots)||![0,3].includes(m.slots.length)||!m.slots.every(p)||!Array.isArray(m.fire)||m.fire.length>128||m.lastPlayer&&!p(m.lastPlayer))return false;
 if(m.copies.some(c=>!mysticCopy(c)||c.owner!==b.id||![0,1].includes(c.slot)||c.id!==-(900000+b.id*10+c.slot)||!p(c)||![0,1].includes(c.hp)||c.maxHp!==1||!int(c.goneAt))||new Set(m.copies.map(c=>c.id)).size!==m.copies.length)return false;
 if(m.fire.some(f=>!p(f)||!['boss','copy','beam'].includes(f.source)||!int(f.born)||f.activeAt!==f.born+1||!int(f.until)||f.until<f.born+5||f.until>m.lastBegin+5)||new Set(m.fire.map(f=>f.x+','+f.y)).size!==m.fire.length)return false;
 if(m.moves.some(w=>!int(w.id)||!p(w.from)||!p(w.to)||!int(w.started)||w.due!==w.started+1))return false;
 if(m.phase===1&&m.cycle>0&&(m.copies.length!==2||m.slots.length!==3||m.danceEnd!==m.danceStart+6||m.revealAt!==m.danceEnd||m.huntAt!==m.revealAt+2||m.deadline!==m.huntAt+8))return false;
 if(m.phase===2&&(b.x!==center(room).x||b.y!==center(room).y||m.copies.some(c=>c.hp>0)||m.shatterAt<0||!p(m.shatterFrom)))return false;
 if(m.state==='open'&&(m.openAt<m.huntAt||m.openUntil!==m.openAt+5)||m.state==='exhausted'&&(m.shots!==4||m.openUntil!==m.openAt+6)||m.state==='dead'&&b.hp>0)return false;
 const shot=w=>w&&p(w.from)&&p(w.target)&&int(w.started)&&w.due===w.started+2&&Number.isInteger(w.index)&&w.index>=1&&w.index<=4&&Array.isArray(w.tiles)&&JSON.stringify(w.tiles)===JSON.stringify(mysticShotTiles(room,w.from,w.target));if(m.shot&&!shot(m.shot)||m.lastShot&&(!shot(m.lastShot)||m.lastShot.impact!==m.lastShot.due)||m.state==='chase'&&!m.shot)return false;return true;}
